Compile/NoErrorOptimize :: list<any>(nth @ list, nth= @ list, nth @ tuple, nth @ string,
     less?, glb, Compile/object!,
     // traces (tformat) are assumed to be correct in cross_compiling
     Core/tformat @ string,
