c1 <: c2(a:integer)  ->  
class c1 extends c2 {
        constructor(a) {
                this.a = a
                }}

fib(x:integer) : integer -> fib(x-1) + fib(x-2)    ->
function fib(x) {
        if (x <= 1) return 1;
        else return fib(x-1) + fib(x-2);
        }

for x in l e(x)  ->
   for (let i = 0; i < l.length; i++) { e(l[i]); }
for x in s e(x)  ->
   for (const s of x) { e(x)}

try e1 catch (set e2)  ->
   try { e1 } catch (e) { if e.belongs(s) {e2}  else {throw e;}} 



