// print a nice indented mark
tr_indent(return?:boolean,n:integer) : void
 -> (if return? printf("[~A]", n)
     else printf("~A:=", n),
     while (n > 9) (princ("="), n := n - 10),
     while (n > 0) (princ(">"), n := n - 1))

