        let t1 := (c_type(x) @ of) in
          (if unique?(t1) class!(the(t1)) else any)
    else any ]

// new : when g_member is x, what the the expected go_type 
[g_expected(s:class) : class 
  -> if (s = float | s = integer) s else any ]    

